from course_model import *

def J(c,id,title,idea,body,cases,question,prompt):
 code='function solve(input) {\n  '+body.replace('\n','\n  ')+'\n}'
 lesson(c,id,title,idea,code,idea,question,js(prompt,code,cases))

c=chapter('js-scope-complete','JavaScript · scope și valori','Blocuri, var, let, const, conversii și comparații.','JavaScript - general.pptx, 3–7; bazele codului de filtrare','braces')
J(c,'scope-var-block','var nu creează scope de bloc','O variabilă var declarată într-un if rămâne în scope-ul funcției care conține blocul. let și const au scope de bloc.','if (input) { var message = "Ready"; }\nreturn typeof message; ',[(True,'string'),(False,'undefined')],q('Ce scope are var în acest exemplu?','Funcția','Doar blocul if','Numai rândul declarației'),'Dacă input este true, declară var message cu textul Ready în if. Returnează typeof message după bloc.')
J(c,'scope-let-shadow','let și două variabile cu același nume','O declarație let într-un bloc poate ascunde temporar numele din exterior; nu îi schimbă automat valoarea.','let price = input;\n{ let price = 99; }\nreturn price;',[(5,5),(12,12)],q('Ce valoare rămâne în variabila exterioară?','Valoarea inițială','99 obligatoriu','undefined obligatoriu'),'Declară price din input. Într-un bloc separat declară alt let price cu 99. Returnează price după bloc.')
J(c,'scope-const-object','const fixează referința','const împiedică reasignarea numelui, nu modificarea proprietăților obiectului referit. Pentru a păstra input nemodificat, construiește un obiect nou.','const product = { name: input };\nproduct.available = true;\nreturn product;',[('Cake',{'name':'Cake','available':True}),('Tea',{'name':'Tea','available':True})],q('Poți modifica o proprietate a unui obiect declarat const?','Da, dacă obiectul nu este înghețat','Nu, niciodată','Doar în CSS'),'Creează un obiect const product cu name din input, adaugă available true și returnează obiectul.')
J(c,'scope-hoisting','Declarația var și inițializarea','Declarația var este disponibilă înaintea liniei sale, dar valoarea atribuită ulterior nu este încă setată. Nu confunda acest comportament cu cel al let.','const before = typeof price;\nvar price = input;\nreturn [before, price];',[(7,['undefined',7])],q('Ce este price înainte de atribuirea valorii aici?','undefined','input deja','O eroare de sintaxă'),'Înainte de var price=input, salvează typeof price. Returnează [tipul anterior,price].')
J(c,'number-parse-int','parseInt citește un întreg','parseInt poate opri citirea când întâlnește un caracter care nu aparține numărului. Specifică baza 10 pentru intenție clară.','return parseInt(input, 10);',[('12px',12),('007',7),('-4 items',-4)],q('Ce produce parseInt("12px",10)?','12','NaN obligatoriu','"12px"'),'Returnează întregul de la începutul textului input, în baza 10.')
J(c,'number-parse-float','parseFloat păstrează partea zecimală','parseFloat poate citi un prefix numeric zecimal. Nu interpretează automat virgula zecimală după regulile limbii utilizatorului.','return parseFloat(input);',[('12.50 EUR',12.5),('-0.25',-0.25)],q('Ce separator zecimal citește forma standard din exemplu?','Punct','Virgulă obligatoriu','Spațiu'),'Citește prefixul numeric zecimal al textului input cu parseFloat.')
J(c,'number-full-conversion','Number cere întregul text numeric','Number("12px") produce NaN, în timp ce parseInt poate returna 12. Folosește Number.isFinite pentru a valida rezultatul ales.','const value = Number(input);\nreturn Number.isFinite(value) ? value : null;',[('12',12),('12px',None),('3.5',3.5)],q('Ce verifică Number.isFinite?','Că valoarea este un număr finit','Că orice text conține cifre','Că există o clasă CSS'),'Convertește întregul input cu Number. Returnează numărul finit sau null.')
J(c,'strict-equality','Comparație strictă','=== compară fără conversia automată dintre text și număr. Valoarea "5" și numărul 5 nu sunt strict egale.','return input.left === input.right;',[({'left':'5','right':5},False),({'left':5,'right':5},True)],q('Ce rezultat are "5" === 5?','false','true','"5"'),'Primești {left,right}. Returnează rezultatul comparației stricte.')
J(c,'nullish-values','Valori lipsă și valori false','Operatorul ?? folosește valoarea de rezervă numai pentru null și undefined; păstrează 0, false și textul gol.','return input.value ?? "Unknown";',[({'value':0},0),({'value':None},'Unknown'),({'value':''},'')],q('Ce valoare păstrează ?? în loc să o înlocuiască?','0','null','undefined'),'Returnează input.value sau Unknown când valoarea este null ori lipsește.')

c=chapter('js-functions-complete','JavaScript · funcțiile ca obiecte','Parametri, arguments, proprietăți și forme de apel.','JavaScript - general.pptx, 8–14','braces')
J(c,'function-last-definition','Funcții cu același nume','Două declarații cu același nume în același scope nu creează supraîncărcări după numărul de parametri. Ultima declarație este cea relevantă în acest exemplu.','function price() { return 1; }\nfunction price(value) { return value * 2; }\nreturn price(input);',[(4,8),(7,14)],q('Creează JavaScript supraîncărcări după numărul parametrilor aici?','Nu','Da','Doar pentru numere'),'Declară price de două ori ca în idee: prima întoarce 1, a doua dublează argumentul. Returnează price(input).')
J(c,'function-name','Numele unei funcții','O funcție este o valoare care poate avea proprietăți. name descrie numele funcției; nu o execută.','function calculateTotal(price, quantity) { return price * quantity; }\nreturn calculateTotal.name;',[(None,'calculateTotal')],q('Ce citește calculateTotal.name?','Numele funcției','Rezultatul apelului','Numele paginii HTML'),'Definește calculateTotal(price,quantity) și returnează proprietatea sa name.')
J(c,'function-length','Numărul parametrilor declarați','length al funcției numără parametrii de dinaintea primului parametru cu valoare implicită; parametrul rest nu este numărat ca o listă de argumente individuale.','function total(price, quantity = 1, ...extras) { return price * quantity; }\nreturn total.length;',[(None,1)],q('Ce valoare are total.length pentru semnătura dată?','1','3','Numărul argumentelor la ultimul apel'),'Definește total(price,quantity=1,...extras) și returnează total.length.')
J(c,'function-arguments','arguments într-o funcție obișnuită','arguments oferă argumentele unei funcții obișnuite. Este array-like, nu un Array complet. Funcțiile arrow nu au propriul arguments.','function countItems() { return arguments.length; }\nreturn countItems(...input);',[([1,2,3],3),([],0)],q('Are o funcție arrow propriul arguments?','Nu','Da','Numai dacă are return'),'Definește countItems ca funcție obișnuită care returnează arguments.length. Apeleaz-o cu elementele din input.')
J(c,'function-rest-array','Rest este un vector','Rest colectează argumentele rămase într-un Array pe care poți aplica map sau reduce.','function sum(...values) { return values.reduce((total,value)=>total+value,0); }\nreturn sum(...input);',[([2,3,4],9),([],0)],q('Ce tip este values declarat prin ...values?','Array','String','HTMLElement'),'Adună toate numerele din input printr-o funcție sum cu parametru rest.')
J(c,'function-constructor','Constructorul Function','Function poate crea o funcție din texte care reprezintă parametri și corpul. Nu îi trimite cod introdus de utilizatori; forma aceasta este studiată pentru înțelegerea sintaxei.','const double = new Function("value", "return value * 2;");\nreturn double(input);',[(3,6),(0,0)],q('Ce primește constructorul Function în exemplu?','Texte care descriu parametrii și corpul','Un selector CSS','Un fișier video'),'Creează prin new Function o funcție double(value) care dublează valoarea și apeleaz-o cu input.')
J(c,'function-return-value','Lipsa unui return','O funcție fără return explicit întoarce undefined. console.log nu înlocuiește return pentru transmiterea unui rezultat către apelant.','function noResult(value) { const copy = value; }\nreturn typeof noResult(input);',[(3,'undefined')],q('Ce întoarce implicit o funcție fără return?','undefined','0','null obligatoriu'),'Definește o funcție fără return, apeleaz-o și returnează typeof rezultatului.')
J(c,'function-default','Valoare implicită și null','Un parametru implicit se aplică la undefined sau argument absent. null este o valoare transmisă și nu declanșează automat valoarea implicită.','function label(value = "Cake") { return value; }\nreturn input.useDefault ? label() : label(input.value);',[({'useDefault':True},'Cake'),({'useDefault':False,'value':None},None)],q('Declanșează null automat parametrul implicit?','Nu','Da','Doar în browser'),'Definește label(value="Cake"). Dacă useDefault este true apelează fără argument, altfel transmite input.value.')

c=chapter('js-collections-complete','JavaScript · colecții și cazuri-limită','Indici, goluri, copiere, sortare și matrici.','JavaScript - general.pptx, 15–64','list')
J(c,'array-sparse-delete','delete nu compactează vectorul','delete elimină proprietatea de la un indice, dar nu micșorează length și nu mută elementele ulterioare. Lucrează pe o copie.','const values = [...input];\ndelete values[1];\nreturn { length: values.length, hasSecond: 1 in values };',[([10,20,30],{'length':3,'hasSecond':False})],q('Ce face delete values[1] cu length?','Îl păstrează','Îl reduce întotdeauna cu 1','Îl setează la zero'),'Copiază input, șterge indicele 1 cu delete și returnează {length,hasSecond}, unde hasSecond verifică 1 in values.')
J(c,'array-splice-removed','splice întoarce elementele eliminate','splice modifică vectorul și întoarce separat elementele eliminate. Copiază input înainte de operație.','const values=[...input];\nconst removed=values.splice(1,2);\nreturn { values, removed };',[([1,2,3,4],{'values':[1,4],'removed':[2,3]})],q('Ce întoarce splice?','Elementele eliminate','Vectorul original nemodificat','Numai noua lungime'),'Elimină două elemente de la indicele 1 pe o copie și returnează {values,removed}.')
J(c,'array-length-truncate','length poate scurta un vector','Setarea unei lungimi mai mici elimină elementele de la final. Indicii încep de la 0.','const values=[...input];\nvalues.length=2;\nreturn values;',[([1,2,3,4],[1,2])],q('Ce rămâne când length devine 2?','Elementele de la indicii 0 și 1','Elementele de la indicii 1 și 2','Ultimele două obligatoriu'),'Primești un vector cu cel puțin două elemente. Returnează o copie scurtată la length 2.')
J(c,'array-default-sort','sort implicit compară texte','Fără comparator, sort ordonează prin reprezentări text; nu este sortare numerică. Pentru numere folosește un comparator.','return [...input].sort();',[([2,10,1],[1,10,2])],q('Ce ordine produce sort() pentru [2,10,1]?','[1,10,2]','[1,2,10]','[2,10,1] mereu'),'Returnează o copie ordonată cu sort fără comparator, pentru a observa regula implicită.')
J(c,'array-desc-tie','Direcția afectează și egalitățile','La sortare descrescătoare pe preț și apoi nume, semnul trebuie aplicat și criteriului secundar.','return [...input].sort((a,b)=>b.price-a.price || b.name.localeCompare(a.name)).map(item=>item.name);',[([{'name':'Cake','price':5},{'name':'Tea','price':5},{'name':'Bread','price':8}],['Bread','Tea','Cake'])],q('Când aplici criteriul secundar?','Când primul comparator întoarce 0','La fiecare element separat de sort','Numai când vectorul este gol'),'Returnează numele ordonate descrescător după price, apoi descrescător după name.')
J(c,'matrix-row-copy','Copiază și rândurile unei matrice','Copierea doar a vectorului exterior păstrează referințele rândurilor. Pentru o matrice de numere poți copia fiecare rând cu map.','const matrix=input.map(row=>[...row]);\nmatrix[0][0]=99;\nreturn matrix;',[([[1,2],[3,4]],[[99,2],[3,4]])],q('Ce rămâne partajat la [...matrix]?','Referințele rândurilor','Numai length','Nimic, este mereu deep copy'),'Copiază matricea și rândurile ei, înlocuiește prima valoare cu 99 și returnează copia fără să modifici input.')
J(c,'array-reduce-empty','Valoare inițială pentru reduce','Un reduce fără valoare inițială nu poate reduce un vector gol. O valoare inițială clară face suma definită și pentru [].','return input.reduce((total,value)=>total+value,0);',[([],0),([1,2],3)],q('Ce valoare inițială folosim la sumă?','0','1','undefined obligatoriu'),'Returnează suma numerelor din input, inclusiv când vectorul este gol.')
J(c,'array-find-not-found','find poate întoarce undefined','find întoarce primul element potrivit sau undefined. Decide explicit ce rezultat oferi când nu găsești.','return input.find(value=>value>10) ?? null;',[([1,12,20],12),([1,2],None)],q('Ce întoarce find când nu găsește?','undefined','-1','[]'),'Returnează primul număr mai mare de 10 sau null dacă nu există.')

c=chapter('regex-complete','JavaScript · expresii regulate pas cu pas','Toate opțiunile, clasele, cuantificatorii și aserțiile din prezentare.','JavaScript - general.pptx, 82–98','text')
regex_tasks=[
 ('constructor','Constructor RegExp','Un backslash într-un string JavaScript trebuie adesea dublat pentru a ajunge în expresia regulată.','return new RegExp("\\\\d+").test(input);',[('a12',True),('abc',False)],'Caută cel puțin o cifră folosind new RegExp și un șir de configurare.'),
 ('flag-i','Flagul i','i ignoră registrul literelor, fără să modifice textul original.','return /^cake$/i.test(input);',[('CAKE',True),('Cake',True),('cake box',False)],'Acceptă numai cuvântul cake, indiferent de litere mari sau mici.'),
 ('flag-g','Flagul g','g caută toate potrivirile; match întoarce null dacă nu există potriviri.','return input.match(/[a-z]+/g) || [];',[('ab12cd',['ab','cd']),('123',[])],'Returnează toate grupurile de litere mici sau [] când nu există.'),
 ('flag-m','Flagul m','Cu m, ^ și $ se pot potrivi la începutul și sfârșitul fiecărei linii.','return input.match(/^[a-z]+$/gm) || [];',[('cake\n12\ntea',['cake','tea'])],'Returnează liniile care conțin numai litere mici ASCII.'),
 ('flag-s','Flagul s','s permite punctului să potrivească și caracterul de linie nouă.','return /^a.b$/s.test(input);',[('a\nb',True),('acb',True),('ab',False)],'Acceptă a, exact un caracter inclusiv linie nouă, apoi b.'),
 ('flag-u','Flagul u','u permite interpretarea Unicode a secvențelor precum \\u{1F600}.','return /\\u{1F600}/u.test(input);',[('Hi 😀',True),('Hi',False)],'Verifică dacă textul conține emoji-ul cu punctul de cod U+1F600 folosind flagul u.'),
 ('flag-d','Flagul d','d pune intervalele de indici în rezultatul exec; capătul intervalului este exclusiv.','const match=/cake/d.exec(input); return match ? match.indices[0] : null;',[('a cake',[2,6]),('tea',None)],'Returnează [start,end] pentru prima apariție cake sau null.'),
 ('flag-y','Flagul y și lastIndex','y cere potrivirea exact de la lastIndex, fără să caute mai în dreapta.','const pattern=/[A-Z]+/y; pattern.lastIndex=input.index; return pattern.test(input.text);',[({'text':'aaABC','index':2},True),({'text':'aaABC','index':1},False)],'Primești {text,index}. Testează un grup de majuscule exact de la index, cu flagul y.'),
 ('digits','\\d și \\D','\\d potrivește o cifră ASCII; \\D potrivește un caracter care nu este cifră.','return input.match(/\\D+/g) || [];',[('12cake34tea',['cake','tea'])],'Returnează grupurile consecutive de caractere care nu sunt cifre.'),
 ('space','\\s și \\S','\\s potrivește caractere de spațiere; \\S reprezintă complementul.','return input.match(/\\S+/g) || [];',[(' cake\t tea\n',['cake','tea'])],'Extrage grupurile de caractere fără spații, taburi sau linii noi.'),
 ('word','\\w și \\W','În forma de bază, \\w include litere ASCII, cifre și underscore; nu este o regulă universală pentru toate cuvintele din toate limbile.','return /^\\w+$/.test(input);',[('cake_12',True),('cake-box',False)],'Acceptă un text nevid format din litere ASCII, cifre și underscore.'),
 ('negated-class','Clasă negată','^ la începutul unei clase între paranteze drepte neagă mulțimea; în afara clasei are alt rol.','return input.match(/[^0-9]+/g) || [];',[('a12b',['a','b'])],'Extrage secvențele care nu sunt cifre folosind o clasă negată.'),
 ('escape-dot','Punct literal','Punctul este metacaracter. Pentru un punct literal folosește \\. în expresia regulată.','return /^cake\\.webp$/.test(input);',[('cake.webp',True),('cakeXwebp',False)],'Acceptă exact numele cake.webp, cu punct real între nume și extensie.'),
 ('quant-star','Zero sau mai multe','* permite zero sau mai multe apariții ale elementului anterior.','return /^ab*c$/.test(input);',[('ac',True),('abbbc',True),('abb',False)],'Acceptă a, oricâte b inclusiv zero, apoi c.'),
 ('quant-plus','Una sau mai multe','+ cere cel puțin o apariție.','return /^ab+c$/.test(input);',[('ac',False),('abc',True)],'Acceptă a, cel puțin un b, apoi c.'),
 ('quant-optional','Zero sau una','? permite lipsa sau o singură apariție a elementului anterior.','return /^colou?r$/.test(input);',[('color',True),('colour',True),('colouur',False)],'Acceptă color și colour, fără alte variante.'),
 ('quant-exact','Număr exact de apariții','{n} cere exact n repetări.','return /^\\d{4}$/.test(input);',[('2026',True),('26',False)],'Acceptă exact patru cifre.'),
 ('quant-min','Limită inferioară','{n,} cere cel puțin n repetări, fără limită superioară declarată.','return /^a{2,}$/.test(input);',[('aa',True),('aaaa',True),('a',False)],'Acceptă numai litera a repetată de cel puțin două ori.'),
 ('quant-range','Interval de repetări','{n,m} include ambele limite.','return /^\\d{2,4}$/.test(input);',[('12',True),('1234',True),('12345',False)],'Acceptă între două și patru cifre, inclusiv limitele.'),
 ('alternation','Alternative și grupare','| reprezintă alternative. Grupează alternativele dacă ancorele trebuie să se aplice întregului rezultat.','return /^(cake|tea)$/.test(input);',[('cake',True),('tea',True),('teapot',False)],'Acceptă exact cake sau tea.'),
 ('capture','Grupuri capturate','Parantezele rotunde pot captura fragmente. Elementul zero este potrivirea completă; primul grup este la indicele 1.','const match=/^(\\w+)-(\\d+)$/.exec(input); return match ? [match[1],Number(match[2])] : null;',[('cake-12',['cake',12]),('cake',None)],'Pentru texte de forma name-number, returnează [name,număr] sau null.'),
 ('greedy','Potrivire greedy','Un cuantificator greedy încearcă să consume cât mai mult, păstrând posibilitatea unei potriviri complete.','return input.match(/<.+>/)?.[0] ?? null;',[('<b>A</b>','<b>A</b>')],'Returnează prima potrivire greedy pentru <.+> sau null. Nu folosi această expresie drept parser HTML.'),
 ('lazy','Potrivire lazy','Un ? după cuantificator îl face lazy: încearcă să consume cât mai puțin.','return input.match(/<.+?>/)?.[0] ?? null;',[('<b>A</b>','<b>')],'Returnează prima potrivire lazy pentru <.+?> sau null.'),
 ('lookahead-positive','Lookahead pozitiv','(?=...) verifică ce urmează fără să includă acea parte în potrivire.','return input.match(/cake(?= box)/g) || [];',[('cake box cake bag',['cake'])],'Extrage cake numai când imediat după el urmează un spațiu și box.'),
 ('lookahead-negative','Lookahead negativ','(?!...) respinge potrivirea dacă partea următoare corespunde expresiei din aserție.','return input.match(/cake(?! box)/g) || [];',[('cake box cake bag',['cake'])],'Extrage cake numai când nu este urmat imediat de un spațiu și box.'),
 ('lookbehind-positive','Lookbehind pozitiv','(?<=...) verifică partea imediat anterioară fără să o includă în rezultat.','return input.match(/(?<=EUR )\\d+/g) || [];',[('EUR 12 USD 7 EUR 4',['12','4'])],'Extrage numerele precedate imediat de EUR și un spațiu.'),
 ('lookbehind-negative','Lookbehind negativ','(?<!...) cere ca expresia verificată să nu apară imediat în stânga. Ai grijă la potriviri parțiale în numere mai lungi.','return input.match(/(?<!x)[A-Z]/g) || [];',[('xAB C',['B','C'])],'Extrage literele mari care nu sunt precedate imediat de x.')]
for key,title,idea,body,cases,prompt in regex_tasks:
 J(c,'regex-full-'+key,title,idea,body,cases,q('Ce regulă aplici în această potrivire?',idea,'Ordonezi alfabetul înainte de căutare','Modifici input înainte de fiecare test'),prompt)

c=chapter('dates-complete','JavaScript · dată și timp','Getter, setter, UTC, luni și intervale în milisecunde.','JavaScript - general.pptx, 99–102; cookie-uri și calendar','calendar')
for method,label,value in [('getUTCMilliseconds','milisecundele din secundă',123),('getUTCSeconds','secundele din minut',6),('getUTCMinutes','minutele din oră',5),('getUTCHours','orele din zi',4),('getUTCDate','ziua din lună',3),('getUTCDay','ziua săptămânii',2),('getUTCMonth','luna numerotată de la zero',1),('getUTCFullYear','anul complet',2026)]:
 J(c,'date-full-'+method,method,f'{method} citește {label} în UTC. Varianta fără UTC folosește fusul orar local al mediului.',f'return new Date(input).{method}();',[('2026-02-03T04:05:06.123Z',value)],q('La ce fus orar se raportează metoda cu UTC?','UTC','Întotdeauna fusul București','Numele fișierului'),'Primești un text ISO. Returnează '+label+' folosind '+method+'.')
for setter,getter,label,args,result in [('setUTCFullYear','getUTCFullYear','anul',2030,2030),('setUTCMonth','getUTCMonth','luna cu indice zero',5,5),('setUTCDate','getUTCDate','ziua lunii',15,15),('setUTCHours','getUTCHours','ora',10,10),('setUTCMinutes','getUTCMinutes','minutul',20,20),('setUTCSeconds','getUTCSeconds','secunda',30,30),('setUTCMilliseconds','getUTCMilliseconds','milisecunda',400,400)]:
 J(c,'date-full-'+setter,setter,'Un setter modifică obiectul Date existent. Lucrează cu o dată nouă pentru a păstra celelalte date nemodificate.',f'const date=new Date("2026-01-01T00:00:00Z"); date.{setter}(input); return date.{getter}();',[(args,result)],q('Ce face un setter Date?','Modifică obiectul Date','Schimbă fusul sistemului','Adaugă un element DOM'),'Creează data 2026-01-01T00:00:00Z, schimbă '+label+' cu '+setter+'(input), apoi citește componenta rezultată.')
J(c,'date-negative-timestamp','Momente înainte de epoca Unix','Un timestamp negativ reprezintă un moment anterior lui 1 ianuarie 1970 UTC.','return new Date(input).toISOString();',[(-1000,'1969-12-31T23:59:59.000Z')],q('Ce indică un timestamp negativ?','Un moment înainte de epoca Unix','O dată invalidă obligatoriu','O durată zero'),'Returnează reprezentarea ISO a timestamp-ului input, inclusiv pentru valori negative.')
J(c,'date-duration-days','Zile ca durată și zile calendaristice','86400000 este numărul de milisecunde din 24 de ore. O zi calendaristică locală poate avea altă durată la schimbarea orei; aici lucrăm cu timestamp-uri UTC.','return (Date.parse(input.end)-Date.parse(input.start))/86400000;',[({'start':'2026-01-01T00:00:00Z','end':'2026-01-03T00:00:00Z'},2)],q('Câte milisecunde au 24 de ore?','86400000','86400','3600000'),'Returnează diferența dintre end și start exprimată în intervale de 24 de ore.')
